/* 중복 이미지 데이터 재사용 · 오프라인 3파일 구조 */
(() => {
  const source = new Map([...document.querySelectorAll('img[data-sky-key]')]
    .map(img => [img.dataset.skyKey, img.getAttribute('src')]));
  for (const image of document.querySelectorAll('img[data-sky-ref]')) {
    const url = source.get(image.dataset.skyRef);
    if (url) image.src = url;
  }
})();

