  const resDate=()=>$('#sc-res-date'),resTime=()=>$('#sc-res-time');
  function dayKey(n){return new Date(n*86400000).toISOString().slice(0,10);}
  function reservationCheck(key,time,now=new Date()){
    const p=kstParts(now);
    if(!/^\d{4}-\d{2}-\d{2}$/.test(key))return '방문 날짜를 선택해 주세요.';
    const ordinal=Date.parse(key+'T00:00:00Z')/86400000;
    if(!Number.isFinite(ordinal)||dayKey(ordinal)!==key||ordinal<p.ordinal||ordinal>p.ordinal+90)return '오늘부터 90일 이내 날짜를 선택해 주세요.';
    if(adminConfig.hours.closed.includes(new Date(ordinal*86400000).getUTCDay()))return '선택한 날짜는 휴무입니다.';
    if(!/^\d{2}:(00|30)$/.test(time))return '이용 가능한 시간을 선택해 주세요.';
    const [h,m]=time.split(':').map(Number);const mins=h*60+m;
    if(mins<adminConfig.hours.open||mins>=adminConfig.hours.close||(ordinal===p.ordinal&&mins<=p.hour*60+p.minute))return '이용 가능한 시간을 선택해 주세요.';
    return '';
  }
  function serviceMessage(id,key='',error=false,detail=''){
    const el=$('#'+id);el.dataset.message=key;el.dataset.detail=detail;el.dataset.error=String(error);
    el.textContent=key?t(key)+(detail?'\n'+detail:''):'';
  }
  function refreshReservation(){
    const p=kstParts();resDate().min=p.key;resDate().max=dayKey(p.ordinal+90);
    const chosen=resTime().value,validDate=resDate().value;
    const first=option('','시간 선택');resTime().replaceChildren(first);
    for(let m=adminConfig.hours.open;m<adminConfig.hours.close;m+=30){
      const val=String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
      if(!reservationCheck(validDate,val)){
        const n=availableSeats(validDate,val,Number($('#sc-res-people').value),$('#sc-res-seat').value).length;
        const item=option(val,val+' · '+n+ex('석',' tables','席'));item.disabled=!n;resTime().append(item);
      }
    }
    if([...resTime().options].some(o=>o.value===chosen&&!o.disabled))resTime().value=chosen;
  }
  function renderReservation(){
    const form=$('#sc-res-form');$$('input,select,button[type=submit]',form).forEach(el=>el.disabled=!!reservation);
    $('#sc-res-cancel').hidden=!reservation;
    if(reservation){const r=reservation;serviceMessage('sc-res-result',r.status==='approved'?'가상 예약 승인':'가상 예약 승인 대기',false,r.date+' '+r.time+' KST · '+t(r.people+'명')+' · '+t({none:'지정 없음',window:'창가석',table:'테이블석'}[r.seat])+(r.table?' · '+r.table:'')+'\n'+t('실제 예약은 접수되지 않았습니다.'));}
    syncReservationUI();
    globalThis.SkyCatEmail?.bind($('#sc-res-mail-status'),'reservation',reservation?globalThis.SkyCatEmail.reservationRef(reservation):null);
  }
  function setupReservation(){
    const mailNote=make('p',''),mailStatus=make('p','');mailStatus.id='sc-res-mail-status';mailStatus.hidden=true;
    $('#sc-res-form button[type=submit]').before(mailNote);$('#sc-res-result').after(mailStatus);globalThis.SkyCatEmail?.notice(mailNote,'reservation');
    refreshReservation();resDate().addEventListener('change',refreshReservation);
    $('#sc-res-form').addEventListener('submit',e=>{
      e.preventDefault();if(syncManagedData().reloading||reservation&&!editingReservation)return;
      const date=resDate().value,time=resTime().value,people=Number($('#sc-res-people').value),seat=$('#sc-res-seat').value;
      const problem=reservationCheck(date,time);
      if(problem){serviceMessage('sc-res-result',problem,true);return;}
      if(!Number.isInteger(people)||people<1||people>6||!['none','window','table'].includes(seat))return;
      const tables=availableSeats(date,time,people,seat);
      const selected=tables.find(x=>x.id===selectedSeat)||(!selectedSeat&&tables[0]);
      if(!selected){serviceMessage('sc-res-result','예약 가능한 좌석을 선택해 주세요.',true);return;}
      reservation={id:reservation?.id||store.key('R'),date,time,people,seat,table:selected.id,status:'pending'};editingReservation=false;selectedSeat=selected.id;extra.reservation=reservation;extra.reservations=extra.reservations.filter(x=>x.id!==reservation.id);extra.reservations.unshift({...reservation});const saved=saveExtra('reservation','reservations');globalThis.SkyCatEmail?.notify('reservation',reservation,saved);renderReservation();renderSeats();
    });
    $('#sc-res-cancel').addEventListener('click',()=>{if(syncManagedData().reloading||!reservation)return;extra.reservations=extra.reservations.filter(x=>x.id!==reservation.id);extra.reservations.unshift({...reservation,status:'cancelled'});reservation=null;editingReservation=false;selectedSeat='';extra.reservation=null;saveExtra('reservation','reservations');renderReservation();refreshReservation();renderSeats();serviceMessage('sc-res-result','가상 예약이 취소되었습니다.');resDate().focus();});
  }
  function setupInquiry(){
    const type=$('#sc-inquiry-type'),message=$('#sc-inquiry-text');
    const mailNote=make('p',''),mailStatus=make('p','');mailStatus.hidden=true;
    $('#sc-inquiry-form .sc-service-actions').before(mailNote);$('#sc-inquiry-result').after(mailStatus);globalThis.SkyCatEmail?.notice(mailNote,'inquiry');
    $('#sc-inquiry-example').addEventListener('click',()=>{type.value='reservation';message.value=t('창가석을 선택할 수 있나요?');});
    $('#sc-inquiry-form').addEventListener('submit',e=>{
      e.preventDefault();
      if(!['reservation','menu','service','other'].includes(type.value)||!message.value.trim()||message.value.length>300){
        serviceMessage('sc-inquiry-result','문의 유형과 내용을 입력해 주세요.',true);return;
      }
      if(syncManagedData().reloading)return;
      const inquiry={id:store.key('Q'),at:Date.now(),category:type.value,body:message.value.trim(),reply:'',status:'pending'};
      extra.inquiries.unshift(inquiry);extra.inquiries=extra.inquiries.slice(0,50);const saved=saveExtra('inquiries');
      globalThis.SkyCatEmail?.notify('inquiry',inquiry,saved);globalThis.SkyCatEmail?.bind(mailStatus,'inquiry',inquiry.id);
      message.value='';type.value='';serviceMessage('sc-inquiry-result','가상 문의 저장 완료');renderInquiries();
    });
  }
