  function isSoldOut(id){return !store.available(id,adminConfig,extra);}
  function sanitizeOptions(id,o){
    if(!o||typeof o!=='object')return defaultOptions();
    return {shot:shotIds.has(id)&&[0,1,2].includes(o.shot)?o.shot:0,
      ice:iceIds.has(id)&&['normal','less','none'].includes(o.ice)?o.ice:'normal',
      sugar:sugarIds.has(id)&&['normal','less','more'].includes(o.sugar)?o.sugar:'normal',
      milk:milkIds.has(id)&&['normal','oat','soy'].includes(o.milk)?o.milk:'normal'};
  }
  function validatedItems(a,historical=false){
    if(!Array.isArray(a))return [];
    const seen=new Set();
    return a.filter(x=>x&&menu.has(x.id)&&validQty(x.n)&&!seen.has(x.id)&&(seen.add(x.id),true)).map(x=>({
      id:x.id,n:x.n,options:sanitizeOptions(x.id,x.options),unit:historical&&Number.isFinite(x.unit)?x.unit:menu.get(x.id).price+optionExtra(sanitizeOptions(x.id,x.options)),name:historical&&x.name?x.name:menu.get(x.id).name
    }));
  }
  function savedArray(v,n){return Array.isArray(v)?v.slice(0,n):[];}
  function loadExtra(){
    extra=store.blank();
    try{
      const raw=store.experience();
      knownExperience=JSON.stringify(raw);
      extra.stock=[...new Set(savedArray(raw.stock,200).filter(id=>menu.has(id)))];
      extra.cart=validatedItems(raw.cart).filter(x=>!isSoldOut(x.id)&&x.n<=store.quantity(x.id,adminConfig));
      extra.recent=[...new Set(savedArray(raw.recent,8).filter(id=>menu.has(id)))];
      extra.orders=savedArray(raw.orders,30).filter(o=>o&&typeof o.id==='string'&&/^SC-[A-Z0-9-]+$/.test(o.id)&&Number.isFinite(o.at)&&Array.isArray(o.items)&&Number.isFinite(o.total)&&o.total>=0).map(o=>({...o,items:validatedItems(o.items,true),step:Math.min(3,Math.max(0,Number(o.step)||0))})).filter(o=>o.items.length);
      extra.memberLog=savedArray(raw.memberLog,40).filter(x=>x&&['stamp','reward','use','adjust'].includes(x.kind)&&typeof x.id==='string'&&Number.isFinite(x.at));
      extra.giftCodes=savedArray(raw.giftCodes,40).filter(x=>x&&/^SKY-[A-Z0-9-]+$/.test(x.code)&&giftValues.includes(x.value)&&typeof x.used==='boolean');
      extra.giftBalance=Number.isInteger(raw.giftBalance)&&raw.giftBalance>=0&&raw.giftBalance<=400000?raw.giftBalance:0;
      extra.reviews=savedArray(raw.reviews,20).filter(x=>x&&[1,2,3,4,5].includes(x.rating)&&['taste','space','kindness','cats'].includes(x.topic)&&Number.isFinite(x.at));
      extra.inquiries=savedArray(raw.inquiries,50).filter(x=>x&&typeof x.id==='string'&&typeof x.body==='string');
      extra.reservations=savedArray(raw.reservations,100).filter(r=>r&&typeof r.id==='string'&&typeof r.date==='string'&&typeof r.time==='string'&&seats.some(s=>s.id===r.table));
      const r=raw.reservation;
      if(r&&r.status!=='cancelled'&&Number.isInteger(r.people)&&r.people>=1&&r.people<=6&&['none','window','table'].includes(r.seat)&&seats.some(s=>s.id===r.table)&&r.date>=store.day())extra.reservation={...r,id:r.id||'legacy-reservation',status:r.status||'pending'};
      if(extra.reservation&&!extra.reservations.some(x=>x.id===extra.reservation.id))extra.reservations.push({...extra.reservation});
    }catch{/* private browsing or invalid storage: start with in-memory defaults */}
  }
  function saveExtra(...fields){
    if(initializing||applyingRemote)return false;
    const latest=store.experience(),unchanged=JSON.stringify(latest)===knownExperience;
    for(const field of fields)latest[field]=extra[field];
    const saved=store.saveExperience(latest);
    if(saved&&unchanged)knownExperience=JSON.stringify(store.experience());
    return saved;
  }
  function saveCart(){
    if(!extraReady||initializing||applyingRemote)return;
    const cart=state.completed?[]:[...state.cart].map(([id,n])=>({id,n,options:customOptions.get(id)||defaultOptions()}));
    const latest=store.experience();
    const unchanged=JSON.stringify(latest)===knownExperience;
    extra.cart=cart;
    // A totals repaint must not overwrite administrator changes or emit another event.
    if(JSON.stringify(latest.cart.map(x=>({id:x?.id,n:x?.n,options:sanitizeOptions(x?.id,x?.options)})))===JSON.stringify(cart))return;
    latest.cart=cart;
    if(store.saveExperience(latest)&&unchanged)knownExperience=JSON.stringify(store.experience());
  }
  function bundleOff(b){
    if(!b||!b.ids?.length||b.ids.some(id=>!menu.has(id)||menu.get(id).archived))return 0;
    return Math.max(0,Math.min(Number(b.off)||0,b.ids.reduce((sum,id)=>sum+menu.get(id).price,0)-1));
  }
  function bundleDiscount(){
    return bundles.reduce((sum,b)=>sum+Math.min(...b.ids.map(id=>state.cart.get(id)||0))*bundleOff(b),0);
  }
  function addItems(ids){
    if(state.completed)resetOrder();
    if(ids.some(id=>isSoldOut(id)||(state.cart.get(id)||0)>=Math.min(5,store.quantity(id,adminConfig))))return false;
    ids.forEach(id=>state.cart.set(id,(state.cart.get(id)||0)+1));
    updateTotals();renderList();loadCustom();return true;
  }
  function refreshExtraTotals(value){
    if(setAmount)setAmount.textContent=value.setDiscount?'− '+money(value.setDiscount):money(0);
    if(giftAmount)giftAmount.textContent=value.giftDiscount?'− '+money(value.giftDiscount):money(0);
    if(giftCheck){giftCheck.disabled=!extra.giftBalance;giftCheck.checked=!!useGift&&extra.giftBalance>0;}
    if(extraReady)saveCart();
  }
  function recordCompletedOrder(c){
    const at=Date.now(),id='SC-'+at.toString(36).toUpperCase()+'-'+Math.random().toString(36).slice(2,6).toUpperCase();
    const order={id,at,step:0,cancelled:false,items:c.items.map(x=>({...x,name:menu.get(x.id).name,options:{...(x.options||defaultOptions())}})),subtotal:c.subtotal,total:c.total,setDiscount:c.setDiscount,discount:c.discount,giftDiscount:c.giftDiscount,shipping:c.shipping,payment:c.payment};
    c.orderId=id;
    extra.orders.unshift(order);extra.orders=extra.orders.slice(0,30);
    const logs=[{kind:'stamp',id,at}];if(c.discount)logs.push({kind:'use',id,at});if(c.reward)logs.push({kind:'reward',id,at});
    extra.memberLog=[...logs,...extra.memberLog].slice(0,40);
    extra.giftBalance=Math.max(0,extra.giftBalance-c.giftDiscount);useGift=false;extra.cart=[];
    for(const x of c.items){const qty=store.quantity(x.id,adminConfig);if(Number.isFinite(qty))adminConfig.inventory[x.id]=Math.max(0,qty-x.n);}
    const savedConfig=store.saveConfig(adminConfig);const savedOrder=saveExtra('orders','memberLog','giftBalance','cart');
    globalThis.SkyCatEmail?.notify('cafe',order,savedConfig&&savedOrder);
    renderOrders();renderMemberHistory();renderGifts();
  }
  const statusLabels=[
    ['주문 접수','Received','注文受付'],['제조 중','Preparing','準備中'],
    ['준비 완료','Ready','準備完了'],['수령 완료','Collected','受取完了']
  ];
  function orderStep(o){return Math.min(3,Math.max(0,Number(o.step)||0));}
  function formatDate(at){return new Intl.DateTimeFormat(currentLanguage==='ko'?'ko-KR':currentLanguage==='ja'?'ja-JP':'en-GB',{timeZone:'Asia/Seoul',dateStyle:'medium',timeStyle:'short'}).format(new Date(at));}
  function statusTrack(o){
    if(o.cancelled)return ux('p','sx-sold','가상 주문 취소','Demo order cancelled','体験注文キャンセル');
    const wrap=make('div','sx-track');wrap.setAttribute('aria-label',copy(statusLabels[orderStep(o)]));
    statusLabels.forEach((s,i)=>{const marker=make('span','sx-stage',copy(s));marker.dataset.done=String(i<=orderStep(o));if(i===orderStep(o))marker.setAttribute('aria-current','step');wrap.append(marker);});
    return wrap;
  }
  function reorder(o){
    if(o.items.some(x=>isSoldOut(x.id)||x.n>store.quantity(x.id,adminConfig))){const s=$('#sx-order-feedback');if(s)s.textContent=ex('품절 또는 재고 부족 상품이 있어 다시 주문할 수 없습니다.','A sold-out or low-stock product prevents reordering.','在庫不足または売切商品があります。');return;}
    if(state.completed)resetOrder();
    state.cart.clear();customOptions.clear();
    o.items.forEach(x=>{state.cart.set(x.id,x.n);customOptions.set(x.id,sanitizeOptions(x.id,x.options));});
    state.shipping=null;state.payment=null;state.useCoupon=false;useGift=false;$$('input[name="shipping"],input[name="payment"]').forEach(el=>el.checked=false);
    updateTotals();loadCustom();renderList();go('full-menu');
  }
