  function addMenuDetail(m,details){
    const unavailable=isSoldOut(m.id);
    if(unavailable)details.prepend(ux('strong','sx-sold','품절 · 예시','Sold out · demo','売切・体験'));
    const i=Number(m.id);
    details.append(xnote('대표 재료 (가상 레시피): '+(ingredientHints[i]||'미정'),'Example ingredients (fictional): '+(ingredientsEN[i]||'Not specified'),'主な材料（架空レシピ）：'+(ingredientsJA[i]||'未設定')));
    const caffeine=m.group==='coffee'||['12','16','19'].includes(m.id);
    details.append(xnote(caffeine?'카페인 함유 가능 · 함량 미확정':'카페인 정보 미확정',caffeine?'May contain caffeine · amount unverified':'Caffeine information unverified',caffeine?'カフェイン含有の可能性・量は未確認':'カフェイン情報は未確認'),
      xnote('알레르기 및 교차접촉 정보 미확정 · 실제 섭취 안전을 보장하지 않습니다.','Allergen and cross-contact information unverified. Not real food safety guidance.','アレルゲン・交差接触情報は未確認。実際の安全性は保証しません。'));
    details.addEventListener('toggle',()=>{if(details.open)rememberMenu(m.id);});
  }
